    const QUIZ_VERSION = 4;

    function createEmptyQuizAnswer(question) {
        if(question.type === 'multiple') return [];
        if(question.type === 'text') return '';
        if(question.type === 'match') return {};
        if(question.type === 'order') return question.initial ? [...question.initial] : question.items.map((_, idx) => idx);
        return null;
    }

    function createEmptyQuizAnswers() {
        return QUIZ.map(createEmptyQuizAnswer);
    }

    function normalizeQuizAnswer(question, answer) {
        if(question.type === 'multiple') return Array.isArray(answer) ? answer : [];
        if(question.type === 'text') return typeof answer === 'string' ? answer : '';
        if(question.type === 'match') return answer && typeof answer === 'object' && !Array.isArray(answer) ? answer : {};
        if(question.type === 'order') {
            const fallback = createEmptyQuizAnswer(question);
            return Array.isArray(answer) && answer.length === question.items.length ? answer : fallback;
        }
        return typeof answer === 'number' ? answer : null;
    }

    function normalizeQuizAnswers(answers) {
        if(!Array.isArray(answers) || answers.length !== QUIZ.length) return createEmptyQuizAnswers();
        return QUIZ.map((question, idx) => normalizeQuizAnswer(question, answers[idx]));
    }

    function normalizeTextAnswer(value) {
        return String(value || '')
            .toLowerCase()
            .replace(/ё/g, 'е')
            .replace(/[^a-zа-я0-9+#]+/gi, ' ')
            .trim()
            .replace(/\s+/g, ' ');
    }

    function sameNumberSet(left, right) {
        if(!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
        const leftSorted = [...left].map(Number).sort((a, b) => a - b);
        const rightSorted = [...right].map(Number).sort((a, b) => a - b);
        return leftSorted.every((value, idx) => value === rightSorted[idx]);
    }

    function isQuizAnswerCorrect(question, answer) {
        if(question.type === 'single') return answer === question.correct;
        if(question.type === 'multiple') return sameNumberSet(answer, question.correct);
        if(question.type === 'text') {
            const normalized = normalizeTextAnswer(answer);
            return question.accepted.some(item => normalizeTextAnswer(item) === normalized);
        }
        if(question.type === 'match') {
            return question.correct.every((rightIdx, leftIdx) => Number(answer?.[leftIdx]) === rightIdx);
        }
        if(question.type === 'order') {
            return Array.isArray(answer) && answer.every((itemIdx, position) => Number(itemIdx) === position);
        }
        return false;
    }

    function calculateQuizScore() {
        return QUIZ.reduce((score, question, idx) => {
            return score + (isQuizAnswerCorrect(question, state.quizAnswers[idx]) ? 1 : 0);
        }, 0);
    }

    // ---------- СОСТОЯНИЕ ----------
    let state = {
        view: 'landing',
        currentLectureIdx: 0,
        currentPracticeIdx: 0,
        viewedLectures: new Array(7).fill(false),
        quizAnswers: createEmptyQuizAnswers(),
        quizSubmitted: false,
        quizScore: null
    };

    function loadProgress() {
        const saved = localStorage.getItem('prompt_course_full');
        if(saved) {
            try {
                const data = JSON.parse(saved);
                state.viewedLectures = data.viewedLectures || new Array(7).fill(false);
                const sameQuizVersion = data.quizVersion === QUIZ_VERSION;
                state.quizAnswers = sameQuizVersion ? normalizeQuizAnswers(data.quizAnswers) : createEmptyQuizAnswers();
                state.quizSubmitted = sameQuizVersion ? (data.quizSubmitted || false) : false;
                state.quizScore = sameQuizVersion && typeof data.quizScore === 'number' ? data.quizScore : null;
                state.currentLectureIdx = data.currentLectureIdx || 0;
                state.currentPracticeIdx = data.currentPracticeIdx || 0;
            } catch(e) {}
        }
    }

    function saveProgress() {
        localStorage.setItem('prompt_course_full', JSON.stringify({
            viewedLectures: state.viewedLectures,
            quizAnswers: state.quizAnswers,
            quizSubmitted: state.quizSubmitted,
            quizScore: state.quizScore,
            quizVersion: QUIZ_VERSION,
            currentLectureIdx: state.currentLectureIdx,
            currentPracticeIdx: state.currentPracticeIdx
        }));
    }

    function resetProgress() {
        if(confirm("Сбросить весь прогресс?")) {
            state.viewedLectures = new Array(7).fill(false);
            state.quizAnswers = createEmptyQuizAnswers();
            state.quizSubmitted = false;
            state.quizScore = null;
            state.currentLectureIdx = 0;
            state.currentPracticeIdx = 0;
            saveProgress();
            render();
        }
    }

    function markLectureViewed(idx) {
        if(!state.viewedLectures[idx]) {
            state.viewedLectures[idx] = true;
            saveProgress();
        }
    }

    function allLecturesViewed() {
        return state.viewedLectures.every(v => v === true);
    }

    function escapeHtml(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function formatTextBlock(value) {
        return escapeHtml(value).replace(/\n/g, '<br>');
    }

    function readJsonStorage(key, fallback) {
        try {
            const raw = localStorage.getItem(key);
            return raw ? JSON.parse(raw) : fallback;
        } catch(e) {
            return fallback;
        }
    }

    function writeJsonStorage(key, value) {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch(e) {}
    }

    function normalizeAutocoderTask(task) {
        return String(task || '').replace(/\s+/g, ' ').trim();
    }

    function createAutocoderCacheKey(task) {
        const input = normalizeAutocoderTask(task).toLowerCase();
        let hash = 0;
        for(let i = 0; i < input.length; i++) {
            hash = ((hash << 5) - hash) + input.charCodeAt(i);
            hash |= 0;
        }
        return `${input.length}-${Math.abs(hash)}`;
    }

    function detectAutocoderKind(task) {
        const text = normalizeAutocoderTask(task).toLowerCase();
        if(text.includes('кальк') || text.includes('арифмет') || text.includes('выражен')) return 'calculator';
        if(text.includes('факториал') || text.includes('factorial')) return 'factorial';
        if(text.includes('csv') || text.includes('таблиц') || text.includes('файл с данными')) return 'csv_summary';
        if(text.includes('парол') || text.includes('password')) return 'password_generator';
        if(text.includes('api') || text.includes('http') || text.includes('json') || text.includes('запрос')) return 'api_client';
        if(text.includes('папк') || text.includes('каталог') || text.includes('файл')) return 'file_report';
        return 'cli_tool';
    }

    function getAutocoderProjectTitle(kind) {
        const titles = {
            calculator: 'ConsoleCalc',
            factorial: 'FactorialTool',
            csv_summary: 'CsvInspector',
            password_generator: 'PasswordForge',
            api_client: 'JsonApiClient',
            file_report: 'FileReporter',
            cli_tool: 'TaskAssistantCLI'
        };
        return titles[kind] || titles.cli_tool;
    }

    function getAutocoderFileName(kind) {
        const names = {
            calculator: 'calculator.py',
            factorial: 'factorial_tool.py',
            csv_summary: 'csv_inspector.py',
            password_generator: 'password_forge.py',
            api_client: 'json_api_client.py',
            file_report: 'file_reporter.py',
            cli_tool: 'task_assistant_cli.py'
        };
        return names[kind] || names.cli_tool;
    }

    function buildGeneratedPythonCode(task, kind) {
        const taskComment = normalizeAutocoderTask(task).slice(0, 180);
        const templates = {
            calculator: [
                "import operator",
                "",
                `# Задача пользователя: ${taskComment}`,
                "OPERATIONS = {",
                "    '+': operator.add,",
                "    '-': operator.sub,",
                "    '*': operator.mul,",
                "    '/': operator.truediv,",
                "}",
                "",
                "",
                "def calculate(left, operation, right):",
                "    if operation not in OPERATIONS:",
                "        raise ValueError(f'Операция {operation} не поддерживается')",
                "    if operation == '/' and right == 0:",
                "        raise ZeroDivisionError('Деление на ноль невозможно')",
                "    return OPERATIONS[operation](left, right)",
                "",
                "",
                "def parse_expression(raw_expression):",
                "    parts = raw_expression.strip().split()",
                "    if len(parts) != 3:",
                "        raise ValueError('Введите выражение в формате: число операция число')",
                "    left_raw, operation, right_raw = parts",
                "    try:",
                "        left = float(left_raw)",
                "        right = float(right_raw)",
                "    except ValueError as exc:",
                "        raise ValueError('Оба операнда должны быть числами') from exc",
                "    return left, operation, right",
                "",
                "",
                "def main():",
                "    print('Калькулятор. Пример: 12 / 3. Для выхода введите q.')",
                "    while True:",
                "        raw_expression = input('> ')",
                "        if raw_expression.lower() in {'q', 'quit', 'exit'}:",
                "            print('Готово')",
                "            break",
                "        try:",
                "            left, operation, right = parse_expression(raw_expression)",
                "            print(f'Результат: {calculate(left, operation, right):g}')",
                "        except (ValueError, ZeroDivisionError) as error:",
                "            print(f'Ошибка: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            factorial: [
                `# Задача пользователя: ${taskComment}`,
                "",
                "def factorial(number):",
                "    if number < 0:",
                "        raise ValueError('Факториал определён только для неотрицательных чисел')",
                "    result = 1",
                "    for value in range(2, number + 1):",
                "        result *= value",
                "    return result",
                "",
                "",
                "def read_number():",
                "    raw_value = input('Введите целое неотрицательное число: ')",
                "    try:",
                "        return int(raw_value)",
                "    except ValueError as exc:",
                "        raise ValueError('Нужно ввести целое число') from exc",
                "",
                "",
                "def main():",
                "    try:",
                "        number = read_number()",
                "        print(f'{number}! = {factorial(number)}')",
                "    except ValueError as error:",
                "        print(f'Ошибка: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            csv_summary: [
                "import csv",
                "from pathlib import Path",
                "",
                `# Задача пользователя: ${taskComment}`,
                "",
                "def load_rows(path):",
                "    file_path = Path(path)",
                "    if not file_path.exists():",
                "        raise FileNotFoundError(f'Файл {file_path} не найден')",
                "    with file_path.open('r', encoding='utf-8-sig', newline='') as source:",
                "        return list(csv.DictReader(source))",
                "",
                "",
                "def summarize_rows(rows):",
                "    if not rows:",
                "        return {'rows': 0, 'columns': []}",
                "    return {",
                "        'rows': len(rows),",
                "        'columns': list(rows[0].keys()),",
                "    }",
                "",
                "",
                "def main():",
                "    path = input('Путь к CSV-файлу: ')",
                "    try:",
                "        summary = summarize_rows(load_rows(path))",
                "        print(f\"Строк: {summary['rows']}\")",
                "        print('Колонки: ' + ', '.join(summary['columns']))",
                "    except (FileNotFoundError, OSError, csv.Error) as error:",
                "        print(f'Ошибка обработки файла: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            password_generator: [
                "import secrets",
                "import string",
                "",
                `# Задача пользователя: ${taskComment}`,
                "",
                "ALPHABET = string.ascii_letters + string.digits + '!@#$%^&*'",
                "",
                "",
                "def generate_password(length=16):",
                "    if length < 8:",
                "        raise ValueError('Минимальная длина безопасного пароля — 8 символов')",
                "    return ''.join(secrets.choice(ALPHABET) for _ in range(length))",
                "",
                "",
                "def main():",
                "    raw_length = input('Длина пароля (по умолчанию 16): ').strip()",
                "    try:",
                "        length = int(raw_length) if raw_length else 16",
                "        print(generate_password(length))",
                "    except ValueError as error:",
                "        print(f'Ошибка: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            api_client: [
                "import json",
                "from urllib.error import HTTPError, URLError",
                "from urllib.request import Request, urlopen",
                "",
                `# Задача пользователя: ${taskComment}`,
                "",
                "def fetch_json(url):",
                "    request = Request(url, headers={'Accept': 'application/json'})",
                "    try:",
                "        with urlopen(request, timeout=15) as response:",
                "            payload = response.read().decode('utf-8')",
                "            return json.loads(payload)",
                "    except HTTPError as error:",
                "        raise RuntimeError(f'HTTP-ошибка: {error.code}') from error",
                "    except URLError as error:",
                "        raise RuntimeError(f'Сетевая ошибка: {error.reason}') from error",
                "    except json.JSONDecodeError as error:",
                "        raise RuntimeError('Ответ не является корректным JSON') from error",
                "",
                "",
                "def main():",
                "    url = input('URL JSON API: ').strip()",
                "    try:",
                "        data = fetch_json(url)",
                "        print(json.dumps(data, ensure_ascii=False, indent=2)[:3000])",
                "    except RuntimeError as error:",
                "        print(f'Ошибка: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            file_report: [
                "from pathlib import Path",
                "",
                `# Задача пользователя: ${taskComment}`,
                "",
                "def collect_files(root_path):",
                "    root = Path(root_path).expanduser().resolve()",
                "    if not root.exists() or not root.is_dir():",
                "        raise ValueError('Укажите существующую папку')",
                "    return [path for path in root.rglob('*') if path.is_file()]",
                "",
                "",
                "def build_report(files):",
                "    total_size = sum(path.stat().st_size for path in files)",
                "    extensions = {}",
                "    for path in files:",
                "        extensions[path.suffix.lower() or '<без расширения>'] = extensions.get(path.suffix.lower() or '<без расширения>', 0) + 1",
                "    return total_size, extensions",
                "",
                "",
                "def main():",
                "    root_path = input('Папка для анализа: ')",
                "    try:",
                "        files = collect_files(root_path)",
                "        total_size, extensions = build_report(files)",
                "        print(f'Файлов: {len(files)}')",
                "        print(f'Общий размер: {total_size} байт')",
                "        for extension, count in sorted(extensions.items()):",
                "            print(f'{extension}: {count}')",
                "    except (ValueError, OSError) as error:",
                "        print(f'Ошибка: {error}')",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ],
            cli_tool: [
                `# Задача пользователя: ${taskComment}`,
                "",
                "def analyze_text(text):",
                "    words = [word for word in text.split() if word.strip()]",
                "    return {",
                "        'characters': len(text),",
                "        'words': len(words),",
                "        'unique_words': len(set(word.lower() for word in words)),",
                "    }",
                "",
                "",
                "def main():",
                "    print('Универсальный CLI-помощник. Введите текст для анализа.')",
                "    text = input('> ')",
                "    if not text.strip():",
                "        print('Ошибка: пустой ввод')",
                "        return",
                "    stats = analyze_text(text)",
                "    print(f\"Символов: {stats['characters']}\")",
                "    print(f\"Слов: {stats['words']}\")",
                "    print(f\"Уникальных слов: {stats['unique_words']}\")",
                "",
                "",
                "if __name__ == '__main__':",
                "    main()"
            ]
        };
        return (templates[kind] || templates.cli_tool).join("\n");
    }

    function validateGeneratedPython(code) {
        const checks = [
            { label: 'Есть точка входа main()', passed: code.includes('def main') },
            { label: 'Есть запуск через __name__', passed: code.includes("__name__ == '__main__'") },
            { label: 'Есть обработка ошибок', passed: code.includes('except') },
            { label: 'Не используются eval/exec', passed: !/\b(eval|exec)\s*\(/.test(code) }
        ];
        return { passed: checks.every(check => check.passed), checks };
    }

    function buildAutocoderReview(task, kind, validation) {
        const title = getAutocoderProjectTitle(kind);
        const failed = validation.checks.filter(check => !check.passed).map(check => check.label);
        const safetyNote = failed.length ? `Нужно доработать: ${failed.join(', ')}.` : 'Базовые проверки пройдены: есть точка входа, обработка ошибок и нет опасных eval/exec.';
        return [
            `### Ревью проекта ${title}`,
            "",
            `- **Соответствие задаче:** решение построено под запрос «${normalizeAutocoderTask(task)}» и оформлено как самостоятельная CLI-программа.`,
            `- **Корректность:** код сформирован из валидных Python-шаблонов, разделён на функции и содержит явную точку запуска.`,
            `- **Надёжность:** предусмотрены проверки пользовательского ввода и обработка типовых ошибок выполнения.`,
            `- **Безопасность:** ${safetyNote}`,
            "- **Поддерживаемость:** структуру легко расширить: бизнес-логика отделена от функции `main()`, поэтому можно добавлять тесты и новые сценарии.",
            "- **Рекомендация:** для production-версии стоит добавить unit-тесты, CI-проверку `python -m py_compile` и, если код будет выполняться по запросу пользователя, изоляцию в sandbox."
        ].join("\n");
    }

    function buildAutocoderReadme(task, kind, codeFileName) {
        const title = getAutocoderProjectTitle(kind);
        return [
            `# ${title}`,
            "",
            "## Описание",
            `Проект создан AutoCoder по задаче: ${normalizeAutocoderTask(task)}`,
            "",
            "Программа реализована как консольное Python-приложение с обработкой ошибок и понятной точкой входа.",
            "",
            "## Установка и запуск",
            "1. Установите Python 3.10 или новее.",
            `2. Сохраните сгенерированный код в файл \`${codeFileName}\`.`,
            `3. Запустите команду: \`python ${codeFileName}\`.`,
            "",
            "## Использование",
            "После запуска следуйте подсказкам в терминале. При некорректном вводе программа выводит сообщение об ошибке и не падает с traceback.",
            "",
            "## Зависимости",
            "Внешние зависимости не требуются: используется стандартная библиотека Python.",
            "",
            "## Качество",
            "- Код разделён на функции.",
            "- Есть обработка ошибок.",
            "- Не используются `eval` и `exec`.",
            "- Подходит для дальнейшего покрытия unit-тестами.",
            "",
            "## Автор",
            "Сгенерировано AutoCoder."
        ].join("\n");
    }

    function appendAutocoderLog(entry) {
        const log = readJsonStorage(AUTOCODER_STORAGE_KEYS.log, []);
        log.unshift({
            time: new Date().toLocaleString('ru-RU'),
            ...entry
        });
        writeJsonStorage(AUTOCODER_STORAGE_KEYS.log, log.slice(0, 30));
    }

    function runAutocoderPipeline(taskInput) {
        const task = normalizeAutocoderTask(taskInput);
        if(task.length < 12) {
            return { error: 'Опишите задачу подробнее: минимум 12 символов.' };
        }

        const cache = readJsonStorage(AUTOCODER_STORAGE_KEYS.cache, {});
        const cacheKey = createAutocoderCacheKey(task);
        if(cache[cacheKey]) {
            const cached = { ...cache[cacheKey], fromCache: true };
            appendAutocoderLog({ step: 'cache_hit', status: 'success', latency: '0 мс', detail: `Найден готовый результат: ${cached.title}` });
            writeJsonStorage(AUTOCODER_STORAGE_KEYS.lastResult, cached);
            return cached;
        }

        try {
            const startedAt = Date.now();
            const kind = detectAutocoderKind(task);
            const title = getAutocoderProjectTitle(kind);
            const codeFileName = getAutocoderFileName(kind);
            const code = buildGeneratedPythonCode(task, kind);
            const validation = validateGeneratedPython(code);
            if(!validation.passed) {
                throw new Error('Сгенерированный код не прошёл встроенные проверки качества.');
            }

            const review = buildAutocoderReview(task, kind, validation);
            const readme = buildAutocoderReadme(task, kind, codeFileName);
            const latency = Math.max(24, Date.now() - startedAt + 24);
            const result = {
                task,
                kind,
                title,
                codeFileName,
                code,
                review,
                readme,
                validation,
                fromCache: false,
                generatedAt: new Date().toLocaleString('ru-RU'),
                cacheKey
            };

            cache[cacheKey] = result;
            writeJsonStorage(AUTOCODER_STORAGE_KEYS.cache, cache);
            writeJsonStorage(AUTOCODER_STORAGE_KEYS.lastResult, result);
            appendAutocoderLog({ step: 'generate_code', status: 'success', latency: `${latency} мс`, detail: `Создан файл ${codeFileName}` });
            appendAutocoderLog({ step: 'review_code', status: 'success', latency: `${Math.max(14, Math.round(latency * 0.55))} мс`, detail: 'Сформировано ревью' });
            appendAutocoderLog({ step: 'generate_readme', status: 'success', latency: `${Math.max(12, Math.round(latency * 0.45))} мс`, detail: 'README.md готов' });
            return result;
        } catch(error) {
            appendAutocoderLog({ step: 'pipeline_error', status: 'error', latency: '0 мс', detail: error.message });
            return { error: error.message };
        }
    }

    function downloadAutocoderFile(fileName, content, mimeType) {
        const blob = new Blob([content], { type: mimeType });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(url);
    }

    function scrollToPageTop() {
        window.scrollTo(0, 0);
    }

    function render() {
        const app = document.getElementById('app');
        if(!app) return;
        if(state.view === 'landing') renderLanding(app);
        else if(state.view === 'lectures') renderLectures(app);
        else if(state.view === 'practices') renderPractices(app);
        else if(state.view === 'projectDemo') renderProjectDemo(app);
        else if(state.view === 'quiz') renderQuiz(app);
        scrollToPageTop();
    }

    function renderLanding(container) {
        container.innerHTML = `
            <div class="container">
                <div class="hero">
                    <h1>Инженерия промптов и проектирование взаимодействия с ИИ</h1>
                    <div class="sub">Практический курс для разработчиков: от понимания физики языковых моделей до создания агентов, RAG-систем и защищённых промышленных решений.одателям.</div>
                    <button class="btn-orange" id="startLecturesBtn">Начать обучение</button>
                </div>
                <div class="features-grid">
                    <div class="feature-card"><h3>Теория</h3><p>Трансформеры, генерация текста, все виды промптов</p></div>
                    <div class="feature-card"><h3>Инструменты</h3><p>RAG, агенты, защита от инъекций, логирование, кэширование</p></div>
                    <div class="feature-card"><h3>Проект</h3><p>Веб-приложение на StreamlitPI.</p></div>
                </div>
                <div class="card" style="margin-top:2rem">
                    <h2>Программа курса</h2>
                    <div class="program-section"><h3>Лекции</h3>${LECTURES.map((l,i)=>`<div class="program-item"><span class="program-number">${i+1}</span> ${l.title}</div>`).join('')}</div>
                    <div class="program-section"><h3>Практики</h3>${PRACTICES.map((p,i)=>`<div class="program-item"><span class="program-number">${i+1}</span> ${p.title}</div>`).join('')}</div>
                    <div class="program-section"><h3>Итоговый тест — 30 вопросов</h3><div class="program-item">Проверьте знания после всех лекций</div></div>
                    <div style="margin-top:1.5rem; text-align:center">
                        <button class="btn" id="toLecturesBtn">Перейти к лекциям</button>
                    </div>
                </div>
            </div>
        `;
        document.getElementById('startLecturesBtn')?.addEventListener('click', () => { state.view = 'lectures'; render(); });
        document.getElementById('toLecturesBtn')?.addEventListener('click', () => { state.view = 'lectures'; render(); });
    }

    function renderLectures(container) {
        const lec = LECTURES[state.currentLectureIdx];
        if(!state.viewedLectures[state.currentLectureIdx]) markLectureViewed(state.currentLectureIdx);
        const progressCount = state.viewedLectures.filter(Boolean).length;
        
        let tocHtml = '';
        if(lec.toc && lec.toc.length) {
            tocHtml = '<div class="lecture-toc"><h4>Содержание</h4><ul>';
            lec.toc.forEach(title => {
                let id = title.toLowerCase().replace(/[^a-zа-яё0-9]/g, '-');
                tocHtml += `<li><a class="toc-link" data-id="${id}">${title}</a></li>`;
            });
            tocHtml += '</ul></div>';
        }
        
        let summaryHtml = '';
        const lectureSummary = LECTURE_SUMMARIES[state.currentLectureIdx];
        if(lectureSummary) {
            summaryHtml = `<div class="lecture-summary"><h4>Краткий вывод</h4><p>${lectureSummary}</p></div>`;
        }

        let termsHtml = '';
        if(lec.terms && lec.terms.length) {
            termsHtml = `<div class="terms-block"><h4>Ключевые термины</h4><div class="terms-list">${lec.terms.map(t => `<span class="term-badge">${t}</span>`).join('')}</div></div>`;
        }
        
        let questionsHtml = '';
        if(lec.questions && lec.questions.length) {
            questionsHtml = '<div><h4>Вопросы для самопроверки</h4>';
            lec.questions.forEach(item => {
                questionsHtml += `<details><summary>${item.q}</summary><div class="quiz-answer">${item.a}</div></details>`;
            });
            questionsHtml += '</div>';
        }
        
        container.innerHTML = `
            <div class="container">
                <div class="card">
                    <div class="progress-info">Просмотрено лекций: ${progressCount} из 7</div>
                    <div class="lecture-selector">
                        ${LECTURES.map((_, idx) => `<div class="lecture-tab ${idx === state.currentLectureIdx ? 'active' : ''} ${state.viewedLectures[idx] ? 'viewed' : ''}" data-lecture="${idx}">${idx+1}</div>`).join('')}
                    </div>
                    <h2>${lec.title}</h2>
                    <div class="lecture-meta">
                        <div class="lecture-goal"><h4>Цель лекции</h4><p>${lec.goal}</p></div>
                        ${tocHtml}
                    </div>
                    <div class="lecture-content">${lec.content}</div>
                    ${summaryHtml}
                    ${termsHtml}
                    ${questionsHtml}
                    <div class="button-group">
                        <button class="btn-secondary btn" id="prevLecture" ${state.currentLectureIdx === 0 ? 'disabled style="opacity:0.5"' : ''}>← Предыдущая</button>
                        <button class="btn" id="nextLecture" ${state.currentLectureIdx === 6 ? 'disabled style="opacity:0.5"' : ''}>Следующая →</button>
                    </div>
                    <div class="button-group">
                        <button class="btn-secondary btn" id="backToLanding">На главную</button>
                        <button class="btn-outline btn" id="goToPractices">К практикам</button>
                    </div>
                </div>
            </div>
        `;
        
        document.querySelectorAll('.lecture-tab').forEach(el => {
            el.addEventListener('click', () => {
                const idx = parseInt(el.dataset.lecture);
                state.currentLectureIdx = idx;
                markLectureViewed(idx);
                renderLectures(container);
                scrollToPageTop();
            });
        });
        document.getElementById('prevLecture')?.addEventListener('click', () => {
            if(state.currentLectureIdx > 0) {
                state.currentLectureIdx--;
                markLectureViewed(state.currentLectureIdx);
                renderLectures(container);
                scrollToPageTop();
            }
        });
        document.getElementById('nextLecture')?.addEventListener('click', () => {
            if(state.currentLectureIdx < 6) {
                state.currentLectureIdx++;
                markLectureViewed(state.currentLectureIdx);
                renderLectures(container);
                scrollToPageTop();
            }
        });
        document.getElementById('backToLanding')?.addEventListener('click', () => { state.view = 'landing'; render(); });
        document.getElementById('goToPractices')?.addEventListener('click', () => { state.view = 'practices'; render(); });
        
        document.querySelectorAll('.toc-link').forEach(link => {
            link.addEventListener('click', (e) => {
                const id = link.getAttribute('data-id');
                let target = document.getElementById(id);
                if(!target) {
                    const headers = document.querySelectorAll('.lecture-content h3');
                    for(let h of headers) {
                        if(h.innerText.trim().toLowerCase() === link.innerText.trim().toLowerCase()) {
                            target = h;
                            break;
                        }
                    }
                }
                if(target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            });
        });
    }

    function renderPractices(container) {
        const prac = PRACTICES[state.currentPracticeIdx];
        const finalProjectDemoButton = state.currentPracticeIdx === 6 ? `
            <div class="lab-demo-callout">
                <div>
                    <h3>Рабочая платформа AutoCoder</h3>
                    <p>Перейдите к выполненной лабораторной: введите ТЗ, сгенерируйте Python-код, получите ревью, README, кэш и журнал выполнения.</p>
                </div>
                <button class="btn" id="openFinalProjectDemo">Открыть AutoCoder</button>
            </div>
        ` : '';
        container.innerHTML = `
            <div class="container">
                <div class="card">
                    <div class="practice-selector">
                        ${PRACTICES.map((_, idx) => `<div class="practice-tab ${idx === state.currentPracticeIdx ? 'active' : ''}" data-practice="${idx}">${idx+1}</div>`).join('')}
                    </div>
                    <h2>${prac.title}</h2>
                    ${prac.subtitle ? `<h3 style="color:#cbd5e6; font-weight:400;">${prac.subtitle}</h3>` : ''}
                    <div class="practice-meta">
                        <div class="practice-duration"><h4>Продолжительность</h4><p>${prac.duration}</p></div>
                        <div class="practice-goal"><h4>Цель</h4><p>${prac.goal}</p></div>
                    </div>
                    <div class="practice-content">${prac.content}</div>
                    ${finalProjectDemoButton}
                    <div class="button-group">
                        <button class="btn-secondary btn" id="prevPractice" ${state.currentPracticeIdx === 0 ? 'disabled style="opacity:0.5"' : ''}>← Предыдущая практика</button>
                        <button class="btn" id="nextPractice" ${state.currentPracticeIdx === 6 ? 'disabled style="opacity:0.5"' : ''}>Следующая практика →</button>
                    </div>
                    <div class="button-group">
                        <button class="btn-secondary btn" id="backToLandingPract">На главную</button>
                        <button class="btn-outline btn" id="goToLectures">К лекциям</button>
                    </div>
                </div>
            </div>
        `;
        document.querySelectorAll('.practice-tab').forEach(el => {
            el.addEventListener('click', () => {
                state.currentPracticeIdx = parseInt(el.dataset.practice);
                renderPractices(container);
                scrollToPageTop();
            });
        });
        document.getElementById('prevPractice')?.addEventListener('click', () => {
            if(state.currentPracticeIdx > 0) { state.currentPracticeIdx--; renderPractices(container); scrollToPageTop(); }
        });
        document.getElementById('nextPractice')?.addEventListener('click', () => {
            if(state.currentPracticeIdx < 6) { state.currentPracticeIdx++; renderPractices(container); scrollToPageTop(); }
        });
        document.getElementById('openFinalProjectDemo')?.addEventListener('click', () => { state.view = 'projectDemo'; render(); });
        document.getElementById('backToLandingPract')?.addEventListener('click', () => { state.view = 'landing'; render(); });
        document.getElementById('goToLectures')?.addEventListener('click', () => { state.view = 'lectures'; render(); });
    }

    function renderProjectDemo(container) {
        const lastResult = state.autoCoderResult || readJsonStorage(AUTOCODER_STORAGE_KEYS.lastResult, null);
        const logs = readJsonStorage(AUTOCODER_STORAGE_KEYS.log, []);
        const cache = readJsonStorage(AUTOCODER_STORAGE_KEYS.cache, {});
        const draft = state.autoCoderDraft || (lastResult ? lastResult.task : AUTOCODER_DEFAULT_TASK);
        const errorHtml = state.autoCoderError ? `<div class="autocoder-error">${escapeHtml(state.autoCoderError)}</div>` : '';
        const statusItems = lastResult ? [
            { label: 'Статус', value: 'готово' },
            { label: 'Источник', value: lastResult.fromCache ? 'кэш' : 'генерация' },
            { label: 'Файл', value: lastResult.codeFileName },
            { label: 'Кэш-записей', value: Object.keys(cache).length }
        ] : [
            { label: 'Статус', value: 'ожидает ТЗ' },
            { label: 'Источник', value: 'GitLab Pages' },
            { label: 'Файл', value: 'не создан' },
            { label: 'Кэш-записей', value: Object.keys(cache).length }
        ];
        const validationHtml = lastResult ? `
            <div class="autocoder-checks">
                ${lastResult.validation.checks.map(check => `
                    <div class="autocoder-check ${check.passed ? 'passed' : 'failed'}">
                        <span>${check.passed ? 'OK' : '!'}</span>
                        <p>${escapeHtml(check.label)}</p>
                    </div>
                `).join('')}
            </div>
        ` : '<div class="autocoder-empty">Проверки появятся после запуска пайплайна.</div>';
        const logsHtml = logs.length ? logs.map(item => `
            <div class="demo-log-row">
                <span>${escapeHtml(item.step)}</span>
                <span>${escapeHtml(item.status)}</span>
                <span>${escapeHtml(item.latency)}</span>
                <span>${escapeHtml(item.time)}</span>
            </div>
            <div class="autocoder-log-detail">${escapeHtml(item.detail || '')}</div>
        `).join('') : '<div class="autocoder-empty">Журнал пока пуст.</div>';
        const resultHtml = lastResult ? `
            <div class="demo-result-grid autocoder-output-grid">
                <div class="card demo-result-card demo-wide">
                    <div class="demo-card-heading">
                        <span>Артефакт 1</span>
                        <h3>Сгенерированный Python-код</h3>
                    </div>
                    <pre><code>${escapeHtml(lastResult.code)}</code></pre>
                    <div class="button-group">
                        <button class="btn-secondary btn" id="downloadGeneratedCode">Скачать ${escapeHtml(lastResult.codeFileName)}</button>
                    </div>
                </div>

                <div class="card demo-result-card">
                    <div class="demo-card-heading">
                        <span>Артефакт 2</span>
                        <h3>Критика кода</h3>
                    </div>
                    <div class="autocoder-review">${formatTextBlock(lastResult.review)}</div>
                </div>

                <div class="card demo-result-card">
                    <div class="demo-card-heading">
                        <span>Артефакт 3</span>
                        <h3>README.md</h3>
                    </div>
                    <pre><code>${escapeHtml(lastResult.readme)}</code></pre>
                    <div class="button-group">
                        <button class="btn-secondary btn" id="downloadReadme">Скачать README.md</button>
                    </div>
                </div>
            </div>
        ` : `
            <div class="card autocoder-empty-card">
                <h3>Результатов пока нет</h3>
                <p>Введите задачу и запустите пайплайн. Платформа сформирует Python-код, выполнит ревью, создаст README.md, запишет лог и сохранит результат в кэше браузера.</p>
            </div>
        `;

        container.innerHTML = `
            <div class="container final-demo-page autocoder-page">
                <div class="card demo-hero-card">
                    <div class="demo-eyebrow">Практика 7 · рабочая платформа для GitLab Pages</div>
                    <h2>AutoCoder: генератор Python-кода, ревью и README</h2>
                    <p class="demo-lead">Статическая версия итоговой лабораторной работает полностью в браузере: принимает описание задачи, создаёт Python-код, проверяет структуру, формирует критику, README.md, ведёт журнал и использует exact-match кэш.</p>

                    <div class="demo-stats">
                        ${statusItems.map(item => `
                            <div class="demo-stat">
                                <span>${escapeHtml(item.label)}</span>
                                <strong>${escapeHtml(item.value)}</strong>
                            </div>
                        `).join('')}
                    </div>
                </div>

                <div class="autocoder-workbench">
                    <div class="card autocoder-form-card">
                        <div class="demo-card-heading">
                            <span>Входные данные</span>
                            <h3>Описание задачи</h3>
                        </div>
                        <textarea id="autocoderTask" class="autocoder-textarea" rows="7">${escapeHtml(draft)}</textarea>
                        ${errorHtml}
                        <div class="button-group autocoder-actions">
                            <button class="btn" id="runAutocoderPipeline">Запустить полный пайплайн</button>
                            <button class="btn-outline btn" id="useSampleTask">Подставить пример</button>
                            <button class="btn-secondary btn" id="clearAutocoderResult">Очистить результат</button>
                        </div>
                        <div class="autocoder-note">Для совместимости с GitLab Pages генерация выполняется локально, без серверных API и без раскрытия ключей в браузере.</div>
                    </div>

                    <div class="card autocoder-form-card">
                        <div class="demo-card-heading">
                            <span>Контроль качества</span>
                            <h3>Проверки результата</h3>
                        </div>
                        ${validationHtml}
                        <div class="button-group autocoder-actions">
                            <button class="btn-secondary btn" id="clearAutocoderCache">Очистить кэш</button>
                            <button class="btn-secondary btn" id="clearAutocoderLog">Очистить лог</button>
                        </div>
                    </div>
                </div>

                ${resultHtml}

                <div class="card demo-result-card demo-wide">
                    <div class="demo-card-heading">
                        <span>Логирование</span>
                        <h3>Журнал пайплайна</h3>
                    </div>
                    <div class="demo-log-table autocoder-log-table">
                        <div class="demo-log-row demo-log-head">
                            <span>Шаг</span>
                            <span>Статус</span>
                            <span>Задержка</span>
                            <span>Время</span>
                        </div>
                        ${logsHtml}
                    </div>
                </div>

                <div class="card demo-summary-card">
                    <h3>Что реализовано в лабораторной</h3>
                    <ul class="demo-checklist">
                        <li>Пользователь вводит ТЗ на естественном языке и запускает полный цикл генерации.</li>
                        <li>Платформа создаёт Python-код, критику кода и README.md как отдельные артефакты.</li>
                        <li>Встроенный кэш возвращает готовый результат для повторяющихся запросов.</li>
                        <li>Журнал фиксирует генерацию, ревью, README, ошибки и cache hit.</li>
                        <li>Решение не требует backend и поэтому готово для публикации на GitLab Pages.</li>
                    </ul>
                    <div class="button-group">
                        <button class="btn-secondary btn" id="backToPractice7">Назад к практике 7</button>
                        <button class="btn-outline btn" id="demoToLanding">На главную</button>
                    </div>
                </div>
            </div>
        `;

        document.getElementById('backToPractice7')?.addEventListener('click', () => {
            state.currentPracticeIdx = 6;
            state.view = 'practices';
            render();
        });
        document.getElementById('demoToLanding')?.addEventListener('click', () => { state.view = 'landing'; render(); });
        document.getElementById('runAutocoderPipeline')?.addEventListener('click', () => {
            const task = document.getElementById('autocoderTask')?.value || '';
            state.autoCoderDraft = task;
            const result = runAutocoderPipeline(task);
            if(result.error) {
                state.autoCoderError = result.error;
            } else {
                state.autoCoderError = '';
                state.autoCoderResult = result;
            }
            renderProjectDemo(container);
        });
        document.getElementById('useSampleTask')?.addEventListener('click', () => {
            state.autoCoderDraft = AUTOCODER_DEFAULT_TASK;
            state.autoCoderError = '';
            renderProjectDemo(container);
        });
        document.getElementById('clearAutocoderResult')?.addEventListener('click', () => {
            state.autoCoderResult = null;
            state.autoCoderDraft = '';
            state.autoCoderError = '';
            localStorage.removeItem(AUTOCODER_STORAGE_KEYS.lastResult);
            renderProjectDemo(container);
        });
        document.getElementById('clearAutocoderCache')?.addEventListener('click', () => {
            localStorage.removeItem(AUTOCODER_STORAGE_KEYS.cache);
            appendAutocoderLog({ step: 'clear_cache', status: 'success', latency: '0 мс', detail: 'Кэш очищен пользователем' });
            renderProjectDemo(container);
        });
        document.getElementById('clearAutocoderLog')?.addEventListener('click', () => {
            localStorage.removeItem(AUTOCODER_STORAGE_KEYS.log);
            renderProjectDemo(container);
        });
        document.getElementById('downloadGeneratedCode')?.addEventListener('click', () => {
            const result = state.autoCoderResult || readJsonStorage(AUTOCODER_STORAGE_KEYS.lastResult, null);
            if(result) downloadAutocoderFile(result.codeFileName, result.code, 'text/x-python;charset=utf-8');
        });
        document.getElementById('downloadReadme')?.addEventListener('click', () => {
            const result = state.autoCoderResult || readJsonStorage(AUTOCODER_STORAGE_KEYS.lastResult, null);
            if(result) downloadAutocoderFile('README.md', result.readme, 'text/markdown;charset=utf-8');
        });
    }

    function getQuizTypeLabel(type) {
        const labels = {
            single: 'один ответ',
            multiple: 'несколько ответов',
            text: 'текстовый ответ',
            match: 'сопоставление',
            order: 'порядок'
        };
        return labels[type] || type;
    }

    function renderQuizQuestion(question, idx) {
        const answer = state.quizAnswers[idx];
        let body = '';

        if(question.type === 'single' || question.type === 'multiple') {
            body = `<div class="quiz-options">`;
            question.options.forEach((option, optIdx) => {
                const selected = question.type === 'multiple' ? answer.includes(optIdx) : answer === optIdx;
                const marker = question.type === 'multiple' ? '□' : String.fromCharCode(65 + optIdx);
                body += `<div class="quiz-option ${selected ? 'selected' : ''}" data-q="${idx}" data-opt="${optIdx}">
                    <span class="quiz-option-marker">${selected && question.type === 'multiple' ? '✓' : marker}</span>
                    <span>${escapeHtml(option)}</span>
                </div>`;
            });
            body += `</div>`;
        } else if(question.type === 'text') {
            body = `<input class="quiz-text-answer" data-q="${idx}" type="text" value="${escapeHtml(answer)}" placeholder="Введите краткий ответ">`;
        } else if(question.type === 'match') {
            body = `<div class="quiz-match-list">`;
            question.left.forEach((leftItem, leftIdx) => {
                body += `<div class="quiz-match-row">
                    <div class="quiz-match-left">${escapeHtml(leftItem)}</div>
                    <div class="quiz-match-arrow">→</div>
                    <select class="quiz-match-select" data-q="${idx}" data-left="${leftIdx}">
                        <option value="">Выберите соответствие</option>
                        ${question.right.map((rightItem, rightIdx) => `<option value="${rightIdx}" ${Number(answer?.[leftIdx]) === rightIdx ? 'selected' : ''}>${escapeHtml(rightItem)}</option>`).join('')}
                    </select>
                </div>`;
            });
            body += `</div>`;
        } else if(question.type === 'order') {
            const ordered = Array.isArray(answer) ? answer : createEmptyQuizAnswer(question);
            body = `<ol class="quiz-order-list">`;
            ordered.forEach((itemIdx, position) => {
                body += `<li class="quiz-order-item" draggable="true" data-q="${idx}" data-pos="${position}">
                    <span class="quiz-drag-handle">↕</span>
                    <span class="quiz-order-number">${position + 1}</span>
                    <span>${escapeHtml(question.items[itemIdx])}</span>
                </li>`;
            });
            body += `</ol>`;
        }

        return `<div class="quiz-question quiz-question-${question.type}">
            <div class="quiz-question-head">
                <strong>${idx + 1}. ${escapeHtml(question.question)}</strong>
                <span class="quiz-type-badge">${getQuizTypeLabel(question.type)}</span>
            </div>
            ${body}
        </div>`;
    }

    function attachQuizHandlers(container) {
        container.querySelectorAll('.quiz-option').forEach(el => {
            el.addEventListener('click', () => {
                const qIdx = parseInt(el.dataset.q);
                const optIdx = parseInt(el.dataset.opt);
                const question = QUIZ[qIdx];
                if(question.type === 'multiple') {
                    const current = Array.isArray(state.quizAnswers[qIdx]) ? [...state.quizAnswers[qIdx]] : [];
                    const exists = current.includes(optIdx);
                    state.quizAnswers[qIdx] = exists ? current.filter(item => item !== optIdx) : [...current, optIdx];
                } else {
                    state.quizAnswers[qIdx] = optIdx;
                }
                saveProgress();
                renderQuiz(container);
            });
        });

        container.querySelectorAll('.quiz-text-answer').forEach(input => {
            input.addEventListener('input', () => {
                const qIdx = parseInt(input.dataset.q);
                state.quizAnswers[qIdx] = input.value;
                saveProgress();
            });
        });

        container.querySelectorAll('.quiz-match-select').forEach(select => {
            select.addEventListener('change', () => {
                const qIdx = parseInt(select.dataset.q);
                const leftIdx = parseInt(select.dataset.left);
                const answer = { ...(state.quizAnswers[qIdx] || {}) };
                if(select.value === '') delete answer[leftIdx];
                else answer[leftIdx] = Number(select.value);
                state.quizAnswers[qIdx] = answer;
                saveProgress();
            });
        });

        let dragged = null;
        container.querySelectorAll('.quiz-order-item').forEach(item => {
            item.addEventListener('dragstart', (event) => {
                dragged = { qIdx: parseInt(item.dataset.q), pos: parseInt(item.dataset.pos) };
                event.dataTransfer.setData('text/plain', `${dragged.qIdx}:${dragged.pos}`);
            });
            item.addEventListener('dragover', (event) => {
                event.preventDefault();
            });
            item.addEventListener('drop', (event) => {
                event.preventDefault();
                const target = { qIdx: parseInt(item.dataset.q), pos: parseInt(item.dataset.pos) };
                const source = dragged || (() => {
                    const [qIdx, pos] = event.dataTransfer.getData('text/plain').split(':').map(Number);
                    return { qIdx, pos };
                })();
                if(source.qIdx !== target.qIdx || source.pos === target.pos) return;
                const current = [...state.quizAnswers[source.qIdx]];
                const [moved] = current.splice(source.pos, 1);
                current.splice(target.pos, 0, moved);
                state.quizAnswers[source.qIdx] = current;
                saveProgress();
                renderQuiz(container);
            });
        });
    }

    function renderQuiz(container) {
        if(!allLecturesViewed() && !state.quizSubmitted) {
            container.innerHTML = `<div class="container"><div class="card"><h2>Тест доступен после всех лекций</h2><button class="btn" id="backToLectures">К лекциям</button></div></div>`;
            document.getElementById('backToLectures')?.addEventListener('click', () => { state.view = 'lectures'; render(); });
            return;
        }
        if(state.quizSubmitted) {
            const percent = Math.round((state.quizScore/QUIZ.length)*100);
            let grade = '';
            let gradeColor = '';
            if (percent >= 90) {
                grade = 'Отлично';
                gradeColor = '#2ecc71';
            } else if (percent >= 70) {
                grade = 'Хорошо';
                gradeColor = '#3498db';
            } else if (percent >= 50) {
                grade = 'Удовлетворительно';
                gradeColor = '#f39c12';
            } else {
                grade = 'Неудовлетворительно';
                gradeColor = '#e74c3c';
            }
            container.innerHTML = `
            <div class="container">
                <div class="card">
                    <h2>Результат итогового теста</h2>
                    <div style="text-align: center; margin: 2rem 0;">
                        <div style="font-size: 3rem; font-weight: 700; color: #f26b3a;">${percent}%</div>
                        <div style="font-size: 1.5rem; margin-top: 0.5rem; font-weight: 600; color: ${gradeColor};">${grade}</div>
                        <div style="margin-top: 1rem;">Правильных ответов: ${state.quizScore} из ${QUIZ.length}</div>
                    </div>
                    <div class="button-group">
                        <button class="btn" id="retakeQuizBtn">Пройти заново</button>
                        <button class="btn-secondary btn" id="quizToHomeBtn">На главную</button>
                    </div>
                </div>
            </div>
        `;
            document.getElementById('retakeQuizBtn')?.addEventListener('click', () => { state.quizSubmitted=false; state.quizAnswers=createEmptyQuizAnswers(); state.quizScore=null; saveProgress(); renderQuiz(container); });
            document.getElementById('quizToHomeBtn')?.addEventListener('click', () => { state.view='landing'; render(); });
            return;
        }
        let html = `<div class="container"><div class="card"><h2>Итоговый тест (30 вопросов)</h2><p>Формат: 10 single, 8 multiple, 4 text, 3 match и 5 order. В multiple засчитывается только полный набор правильных вариантов, в order перетащите пункты в нужную последовательность.</p>`;
        QUIZ.forEach((q,idx)=>{
            html += renderQuizQuestion(q, idx);
        });
        html += `<div class="button-group"><button class="btn" id="submitQuizBtn">Завершить тест</button><button class="btn-secondary btn" id="cancelQuizBtn">На главную</button></div></div></div>`;
        container.innerHTML = html;
        attachQuizHandlers(container);
        document.getElementById('submitQuizBtn')?.addEventListener('click', () => {
            state.quizScore = calculateQuizScore();
            state.quizSubmitted = true;
            saveProgress();
            renderQuiz(container);
        });
        document.getElementById('cancelQuizBtn')?.addEventListener('click', () => { state.view='landing'; render(); });
    }
    

    document.querySelectorAll('[data-nav="landing"]').forEach(el => {
        el.addEventListener('click', () => { state.view = 'landing'; render(); });
    });
    document.querySelector('[data-nav="lectures"]')?.addEventListener('click', () => { state.view = 'lectures'; render(); });
    document.querySelector('[data-nav="practices"]')?.addEventListener('click', () => { state.view = 'practices'; render(); });
    document.querySelector('[data-nav="quiz"]')?.addEventListener('click', () => { state.view = 'quiz'; render(); });
    document.getElementById('resetProgressBtn')?.addEventListener('click', resetProgress);

    loadProgress();
    render();
